def clean_json(data: dict) -> dict:
    """
    Clean the provided JSON data by removing any None values and empty strings.

    Args:
        data (dict): The dictionary to be cleaned.

    Returns:
        dict: The cleaned dictionary without None values and empty strings.

    Raises:
        TypeError: If the provided data is not a dictionary.
    """
    if not isinstance(data, dict):
        raise TypeError("Provided data must be a dictionary")

    def clean_dict(d):
        return {k: v for k, v in ((k, clean(v)) for k, v in d.items() if v is not None and v != "")}

    def clean(value):
        if isinstance(value, dict):
            return clean_dict(value)
        elif isinstance(value, list):
            return [clean(item) for item in value if item is not None and item != ""]
        else:
            return value

    return clean_dict(data)
